# 用类封装数据清洗逻辑
class DataCleaner:
    def __init__(self, remove_empty=True):
        self.remove_empty = remove_empty

    def clean(self, items):
        result = []
        for item in items:
            if item is None:
                continue
            s = str(item).strip()
            if self.remove_empty and s == '':
                continue
            result.append(s)
        return result

cleaner = DataCleaner()
print(cleaner.clean([' 苹果 ', '', None, '香蕉 ']))   # ['苹果', '香蕉']

